// Archive every closed (Done/Canceled/Duplicate) non-archived issue in team MM
// via Linear's issueArchive mutation — the alternative to deleting issues to
// stay under the free plan's 250 active-issue cap (archived issues don't count).
//
// Dry run (default):  node linear-export/archive-done.mjs
// Actually archive:   node linear-export/archive-done.mjs --yes
//
// Run from the repo root (reads LINEAR_API_KEY from .env.local). Archiving is
// reversible in Linear (issues stay searchable under "archived"), unlike delete.
import { readFileSync } from "node:fs";

const YES = process.argv.includes("--yes");
const envLine = readFileSync(".env.local", "utf8")
  .split("\n")
  .find((l) => l.includes("LINEAR_API_KEY"));
if (!envLine) throw new Error("LINEAR_API_KEY not found in .env.local");
const API_KEY = envLine.replace(/^export\s+/, "").split("=").slice(1).join("=").trim().replace(/^["']|["']$/g, "");

async function gql(query, variables) {
  const res = await fetch("https://api.linear.app/graphql", {
    method: "POST",
    headers: { "Content-Type": "application/json", Authorization: API_KEY },
    body: JSON.stringify({ query, variables }),
  });
  const json = await res.json();
  if (json.errors) throw new Error(JSON.stringify(json.errors));
  return json.data;
}

// Collect candidates: non-archived, state type completed or canceled
// (covers Done, Canceled, and Duplicate).
const LIST = `
query ($after: String) {
  issues(first: 50, after: $after, filter: {
    team: { key: { eq: "MM" } }
    state: { type: { in: ["completed", "canceled"] } }
  }) {
    pageInfo { hasNextPage endCursor }
    nodes { id identifier title archivedAt state { name } }
  }
}`;

const candidates = [];
let after = null;
for (;;) {
  const d = await gql(LIST, { after });
  candidates.push(...d.issues.nodes.filter((i) => !i.archivedAt));
  if (!d.issues.pageInfo.hasNextPage) break;
  after = d.issues.pageInfo.endCursor;
}
console.log(`${candidates.length} closed, unarchived issues in team MM`);

if (!YES) {
  for (const i of candidates) console.log(`  would archive ${i.identifier} [${i.state.name}] ${i.title.slice(0, 60)}`);
  console.log("\nDry run — re-run with --yes to archive.");
  process.exit(0);
}

const ARCHIVE = `mutation ($id: String!) { issueArchive(id: $id) { success } }`;
let ok = 0, failed = 0;
for (const i of candidates) {
  try {
    const d = await gql(ARCHIVE, { id: i.id });
    if (d.issueArchive.success) ok++;
    else { failed++; console.error(`  failed (no success): ${i.identifier}`); }
  } catch (e) {
    failed++;
    console.error(`  failed: ${i.identifier} — ${e.message.slice(0, 120)}`);
  }
  // Gentle pacing to stay under API rate limits.
  await new Promise((r) => setTimeout(r, 150));
  if ((ok + failed) % 25 === 0) console.log(`  ${ok + failed}/${candidates.length}...`);
}
console.log(`archived ${ok}, failed ${failed}. Active issue count should now be ~${224 - ok}.`);

