1	// pattern: Imperative Shell
2	
3	use axum::{extract::FromRequestParts, http::request::Parts};
4	use common::ApiError;
5	
6	use crate::app::AppState;
7	
8	use common::ErrorCode;
9	
10	use super::bearer::extract_bearer_token;
11	use super::dpop::validate_dpop;
12	use super::jwt::{parse_scope, verify_access_token, AuthScope};
13	
14	/// Axum extractor that validates a Bearer (or DPoP-bound) JWT and yields the
15	/// authenticated caller's DID and scope.
16	///
17	/// Extract this in any handler that requires authentication:
18	/// ```rust,ignore
19	/// async fn my_handler(user: AuthenticatedUser) -> impl IntoResponse { ... }
20	/// ```
21	#[derive(Debug, Clone)]
22	pub struct AuthenticatedUser {
23	    pub did: String,
24	    pub scope: AuthScope,
25	    /// Raw `scope` claim. OAuth tokens carry the granular grant here; legacy
26	    /// session/app-password tokens carry their `com.atproto.*` scope string.
27	    pub scope_claim: String,
28	    /// Agent registration id, present only when this token was derived from an auth.md agent
29	    /// `identity_assertion`. `Some(_)` marks the caller as an agent; ordinary session/OAuth tokens
30	    /// carry `None`.
31	    pub registration_id: Option<String>,
32	}
33	
34	impl AuthenticatedUser {
35	    /// Whether this caller is an auth.md agent (its token carries a `registration_id`).
36	    pub fn is_agent(&self) -> bool {
37	        self.registration_id.is_some()
38	    }
39	
40	    /// Reject an agent-derived caller from a route reserved for the account holder's own full
41	    /// session. Agent tokens map to [`AuthScope::Access`] for coarse admission, so a route that
42	    /// gates on `AuthScope::Access` alone (with no granular `require_*` mapping — e.g. app-password
43	    /// management) would otherwise admit an agent; this closes that gap. Ordinary session/OAuth
44	    /// callers are unaffected.
45	    pub fn require_not_agent(&self) -> Result<(), ApiError> {
46	        if self.is_agent() {
47	            return Err(ApiError::new(
48	                ErrorCode::InsufficientScope,
49	                "this operation is not available to agent-derived credentials",
50	            ));
51	        }
52	        Ok(())
53	    }
54	}
55	
56	impl FromRequestParts<AppState> for AuthenticatedUser {
57	    type Rejection = ApiError;
58	
59	    async fn from_request_parts(
60	        parts: &mut Parts,
61	        state: &AppState,
62	    ) -> Result<Self, Self::Rejection> {
63	        // 1. Extract the raw Bearer token string from Authorization header.
64	        let token_str = extract_bearer_token(&parts.headers)?;
65	
66	        // 2. Detect the DPoP header before decoding the access token.
67	        //    RFC 9449 §11.1: reject if multiple DPoP headers are present — a
68	        //    header-prepending proxy could inject a forged proof as the first value.
69	        if parts.headers.get_all("DPoP").iter().count() > 1 {
70	            return Err(ApiError::new(
71	                common::ErrorCode::InvalidToken,
72	                "multiple DPoP headers are not permitted",
73	            ));
74	        }
75	        let dpop_value = parts
76	            .headers
77	            .get("DPoP")
78	            .and_then(|v| {
79	                v.to_str()
80	                    .inspect_err(|_| {
81	                        tracing::warn!("DPoP header contains non-UTF-8 bytes; treating as absent");
82	                    })
83	                    .ok()
84	            })
85	            .map(str::to_owned);
86	        let has_dpop = dpop_value.is_some();
87	
88	        // 3. Decode and verify the access token (HS256 or ES256).
89	        let claims = verify_access_token(token_str, state)?;
90	
91	        // 4. Enforce DPoP binding (RFC 9449 §7.1).
92	        //    When `cnf` is present the token carries a proof-of-possession claim; we
93	        //    must require a DPoP proof to honour that binding.
94	        //    * `cnf` present but no `jkt` → explicit rejection: a future cnf variant
95	        //      (e.g. `x5t#S256` for cert binding) could be silently downgraded to plain
96	        //      Bearer if we only check `jkt.is_some()`.
97	        //    * `cnf.jkt` present but no DPoP header → downgrade attack; reject.
98	        if let Some(cnf) = &claims.cnf {
99	            if cnf.jkt.is_none() {
100	                return Err(ApiError::new(
101	                    common::ErrorCode::InvalidToken,
102	                    "access token cnf present without jkt binding",
103	                ));
104	            }
105	            if !has_dpop {
106	                return Err(ApiError::new(
107	                    common::ErrorCode::InvalidToken,
108	                    "DPoP-bound token requires a DPoP proof header",
109	                ));
110	            }
111	        }
112	
113	        // 5. Resolve scope enum.
114	        let scope = parse_scope(&claims.scope)?;
115	
116	        // 6. DPoP proof validation — only when the DPoP header is present.
117	        if has_dpop {
118	            let dpop_token = dpop_value.as_deref().unwrap();
119	            validate_dpop(
120	                dpop_token,
121	                &parts.method,
122	                &parts.uri,
123	                &state.config.public_url,
124	                &claims,
125	                token_str,
126	            )?;
127	        }
128	
129	        Ok(AuthenticatedUser {
130	            did: claims.sub,
131	            scope,
132	            scope_claim: claims.scope,
133	            registration_id: claims.registration_id,
134	        })
135	    }
136	}
137	
138	#[cfg(test)]
139	mod tests {
140	    use super::*;
141	
142	    fn user(registration_id: Option<&str>) -> AuthenticatedUser {
143	        AuthenticatedUser {
144	            did: "did:plc:test000000000000000".to_string(),
145	            scope: AuthScope::Access,
146	            scope_claim: "atproto repo:*?action=create&action=update".to_string(),
147	            registration_id: registration_id.map(str::to_string),
148	        }
149	    }
150	
151	    #[test]
152	    fn require_not_agent_rejects_agent_and_allows_others() {
153	        // An agent-derived caller (registration_id present) is refused with InsufficientScope (403).
154	        let err = user(Some("reg_1")).require_not_agent().unwrap_err();
155	        assert_eq!(err.status_code(), 403);
156	        // An ordinary session/OAuth caller passes.
157	        assert!(user(None).require_not_agent().is_ok());
158	    }
159	
