1048	    fn dpop_key_to_jwk(key: &SigningKey) -> serde_json::Value {
1049	        let vk = key.verifying_key();
1050	        let point = vk.to_encoded_point(false);
1051	        let x = URL_SAFE_NO_PAD.encode(point.x().unwrap());
1052	        let y = URL_SAFE_NO_PAD.encode(point.y().unwrap());
1053	        serde_json::json!({ "kty": "EC", "crv": "P-256", "x": x, "y": y })
1054	    }
1055	
1056	    fn dpop_thumbprint(key: &SigningKey) -> String {
1057	        let jwk = dpop_key_to_jwk(key);
1058	        // RFC 7638 requires keys to be in lexicographic order (crv, kty, x, y for EC keys).
1059	        // Do NOT reorder these keys, or the thumbprint will differ silently.
1060	        let canonical = serde_json::to_string(&serde_json::json!({
1061	            "crv": jwk["crv"],
1062	            "kty": jwk["kty"],
1063	            "x": jwk["x"],
1064	            "y": jwk["y"],
1065	        }))
1066	        .unwrap();
1067	        let hash = Sha256::digest(canonical.as_bytes());
1068	        URL_SAFE_NO_PAD.encode(hash)
1069	    }
1070	
1071	    fn make_dpop_proof(
1072	        key: &SigningKey,
1073	        htm: &str,
1074	        htu: &str,
1075	        nonce: Option<&str>,
1076	        iat: i64,
1077	    ) -> String {
1078	        let jwk = dpop_key_to_jwk(key);
1079	        let header = serde_json::json!({ "typ": "dpop+jwt", "alg": "ES256", "jwk": jwk });
1080	        let mut payload = serde_json::json!({ "htm": htm, "htu": htu, "iat": iat, "jti": Uuid::new_v4().to_string() });
1081	        if let Some(n) = nonce {
1082	            payload["nonce"] = serde_json::Value::String(n.to_string());
1083	        }
1084	        let hdr = URL_SAFE_NO_PAD.encode(serde_json::to_string(&header).unwrap().as_bytes());
1085	        let pay = URL_SAFE_NO_PAD.encode(serde_json::to_string(&payload).unwrap().as_bytes());
1086	        let sig_input = format!("{hdr}.{pay}");
1087	        let sig: Signature = key.sign(sig_input.as_bytes());
1088	        let sig_b64 = URL_SAFE_NO_PAD.encode(sig.to_bytes().as_ref() as &[u8]);
1089	        format!("{hdr}.{pay}.{sig_b64}")
1090	    }
