1	// pattern: Functional Core
2	//
3	// Pure rendering functions for the OAuth consent UI. All inputs are plain data; all
4	// outputs are plain strings or Axum response types that carry no side effects.
5	// No I/O, no database, no AppState.
6	//
7	// Visual system: "The Sealed Credential" (see DESIGN.md). Brand fonts are served by the
8	// the PDS's own /static/fonts route (no third-party CDN — an auth page must not leak logins).
9	
10	use axum::http::StatusCode;
11	use axum::response::{Html, Redirect};
12	
13	// ── Public rendering functions ────────────────────────────────────────────────
14	
15	/// Build an OAuth error redirect (303) to `redirect_uri` with error parameters.
16	pub(super) fn error_redirect(
17	    redirect_uri: &str,
18	    error: &str,
19	    description: &str,
20	    state: &str,
21	) -> Redirect {
22	    let sep = if redirect_uri.contains('?') { '&' } else { '?' };
23	    let url = format!(
24	        "{}{}error={}&error_description={}&state={}",
25	        redirect_uri,
26	        sep,
27	        encode_param(error),
28	        encode_param(description),
29	        encode_param(state),
30	    );
31	    Redirect::to(&url)
32	}
33	
34	/// Render a standalone HTML error page for cases where redirecting is unsafe
35	/// (unknown `client_id`, mismatched `redirect_uri`).
36	pub(super) fn error_page(title: &str, message: &str) -> (StatusCode, Html<String>) {
37	    let mut html = String::with_capacity(2048);
38	    html.push_str(ERROR_PAGE_HEADER);
39	    html.push_str(&html_escape(title));
40	    html.push_str("</title>\n  <style>");
41	    html.push_str(FONT_FACES);
42	    html.push_str(ERROR_CSS);
43	    html.push_str("  </style>\n</head>\n<body>\n");
44	    html.push_str(
45	        "  <div class=\"card\">\n    <div class=\"top\">\n      <span class=\"seal alarm\">",
46	    );
47	    html.push_str(ICON_ALARM);
48	    html.push_str("</span>\n      <h1>");
49	    html.push_str(&html_escape(title));
50	    html.push_str("</h1>\n      <p class=\"err-msg\">");
51	    html.push_str(&html_escape(message));
52	    html.push_str("</p>\n    </div>\n  </div>\n</body>\n</html>");
53	    (StatusCode::BAD_REQUEST, Html(html))
54	}
55	
56	/// Render the OAuth consent + sign-in page.
57	///
58	/// All user-controlled values are HTML-escaped before insertion.
