s = s.replace(old, new)

# add refreshDidDoc to the ipc import
import re
m = re.search(r"import \{[^}]*getStoredDidDoc[^}]*\} from '\$lib/ipc';", s)
assert m, "ipc import not found"
imp = m.group(0)
assert "refreshDidDoc" not in imp
new_imp = imp.replace("getStoredDidDoc,", "getStoredDidDoc,\n    refreshDidDoc,")
s = s.replace(imp, new_imp)
open(p, "w").write(s)
print("IdentityListHome updated")
EOF
